{"name": "ranked-choice", "type": "module", "private": true, "scripts": {"test": "node --test test/*.test.js"}}
---
import { spawnSync } from 'node:child_process'
import assert from 'node:assert/strict'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const cli = fileURLToPath(new URL('../src/cli.js', import.meta.url))
const RACE = 'candidates alice bob carol\nballot 4 alice bob\nballot 3 bob carol\nballot 2 carol bob\nballot 1 carol\n'

function run(argv, stdin = '') {
  const result = spawnSync(process.execPath, [cli, ...argv], { encoding: 'utf8', input: stdin })
  return { code: result.status, out: result.stdout, err: result.stderr }
}

test('a first-round majority wins at once', () => {
  const input = 'candidates a b\nballot 3 a\nballot 1 b\n'
  assert.deepEqual(run(['rounds'], input), { code: 0, out: 'round 1: a=3 b=1 exhausted=0\nwinner a\n', err: '' })
})

test('the runoff transfers votes from the eliminated candidate', () => {
  assert.equal(run(['rounds'], RACE).out, 'round 1: alice=4 bob=3 carol=3 exhausted=0\neliminated carol\nround 2: bob=5 alice=4 exhausted=1\nwinner bob\n')
})

test('tally prints only the round count and the outcome', () => {
  assert.deepEqual(run(['tally'], RACE), { code: 0, out: 'rounds 2\nwinner bob\n', err: '' })
})

test('a ballot whose choices are all eliminated becomes exhausted', () => {
  assert.equal(run(['rounds'], 'candidates a b c\nballot 3 a\nballot 2 b\nballot 1 c\n').out, 'round 1: a=3 b=2 c=1 exhausted=0\neliminated c\nround 2: a=3 b=2 exhausted=1\nwinner a\n')
})

test('counts are listed by descending votes and then by name', () => {
  assert.equal(run(['rounds'], 'candidates zeta alpha\nballot 1 zeta\nballot 1 alpha\n').out.split('\n')[0], 'round 1: alpha=1 zeta=1 exhausted=0')
})

test('a candidate nobody ranked still appears with zero', () => {
  assert.equal(run(['rounds'], 'candidates a b c\nballot 1 a\n').out, 'round 1: a=1 b=0 c=0 exhausted=0\nwinner a\n')
})

test('an election with no ballot has no winner', () => {
  assert.deepEqual(run(['rounds'], 'candidates a b\n'), { code: 0, out: 'round 1: a=0 b=0 exhausted=0\nno winner\n', err: '' })
})

test('blank lines and comments are ignored', () => {
  assert.equal(run(['tally'], '# vote\n\ncandidates a\nballot 1 a\n').out, 'rounds 1\nwinner a\n')
})

test('a ballot before the candidates is rejected', () => {
  const result = run(['tally'], 'ballot 1 a\ncandidates a\n')
  assert.equal(result.code, 2)
  assert.equal(result.out, '')
  assert.equal(result.err, 'error: line 1: candidates must be declared once, before any ballot\n')
})

test('a second candidates line is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\ncandidates b\n').err, 'error: line 2: candidates must be declared once, before any ballot\n')
})

test('a ballot naming an undeclared candidate is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nballot 1 z\n').err, 'error: line 2: unknown candidate z\n')
})

test('a ballot that repeats a candidate is rejected', () => {
  assert.equal(run(['tally'], 'candidates a b\nballot 1 a b a\n').err, 'error: line 2: candidate a is repeated\n')
})

test('a non-positive ballot count is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nballot 0 a\n').err, 'error: line 2: count must be a positive integer\n')
})

test('an input with no candidates line is rejected', () => {
  assert.equal(run(['tally'], '# nothing\n').err, 'error: no candidates\n')
})

test('an unknown directive is rejected', () => {
  assert.equal(run(['tally'], 'candidates a\nvote 1 a\n').err, 'error: line 2: unknown directive vote\n')
})

test('an unknown mode is rejected', () => {
  const result = run(['count'], RACE)
  assert.equal(result.code, 2)
  assert.equal(result.err, 'error: usage: cli.js rounds|tally\n')
})
---
{
  "id": "code:ranked-choice",
  "tier": 5,
  "domain": "data-structures-algorithms",
  "title": "Run an instant-runoff count with a backwards tie-break",
  "prompt": "`src/cli.js` is the program; how the work is split across other files under `src/` is up to you. It takes exactly one argument, `rounds` or `tally`, and reads an election from standard input. Split the input on newlines and drop the empty tail a trailing newline leaves. Trim each line; ignore it when it is empty or begins with `#`; otherwise split it on runs of whitespace. Exit 0 whenever the election parses.\n\nThe line `candidates <name>...` declares the field. It must appear exactly once, before any ballot, and must name at least one candidate; a name is one or more of the characters `A` to `Z`, `a` to `z`, `0` to `9`, `_` and `-`, and no name may repeat. The line `ballot <count> <candidate>...` records `count` identical ballots ranking those candidates from most to least preferred. The count is a decimal integer of at least 1 written without a sign and without a leading zero, a ballot names at least one candidate, every name must have been declared, and no ballot may name a candidate twice. A ballot need not rank every candidate.\n\nCount in rounds. Every candidate starts continuing. In each round every ballot counts for the first candidate on it that is still continuing; a ballot whose named candidates are all eliminated is exhausted and counts for nobody. Let the active total be the number of ballots that counted for someone. When the active total is 0 the election ends with no winner. When some candidate's count, doubled, is greater than the active total, that candidate wins and the election ends. Otherwise exactly one candidate is eliminated and another round is counted.\n\nThe candidate eliminated is the one with the fewest votes in this round. When several tie for fewest, compare them across the rounds already counted, this one included, from the first round onwards: at the first round where their counts are not all equal, keep only those with the fewest votes in that round and compare the survivors the same way from the first round again. When no round separates them, eliminate the one whose name sorts last by code point.\n\n`rounds` prints, for each round in order, `round K: ` followed by one `<name>=<votes>` for every continuing candidate, separated by single spaces, and then `exhausted=<n>`. Candidates are listed by descending vote count, and by ascending name where counts tie. A round that eliminated someone is followed by the line `eliminated <name>`. `tally` instead prints one line, `rounds N`, holding how many rounds were counted. Both modes end with `winner <name>`, or `no winner` when no candidate ever reached the majority.\n\nA failure writes one line to standard error and exits 2, having written nothing to standard output; stop at the first one. The messages are `error: usage: cli.js rounds|tally` when the argument is not exactly one of the two mode words; `error: line N: candidates must be declared once, before any ballot`; `error: line N: expected candidates <name>...`; `error: line N: invalid candidate name <name>`; `error: line N: candidate <name> is declared twice`; `error: line N: expected ballot <count> <candidate>...`; `error: line N: count must be a positive integer`; `error: line N: unknown candidate <name>`; `error: line N: candidate <name> is repeated`; `error: line N: unknown directive <word>`; and `error: no candidates`, with no line number, when the input declares none.",
  "heldOut": false,
  "immutable": [
    "test",
    "package.json"
  ],
  "checks": [
    {
      "id": "tests-pass",
      "outcome": "the test suite passes",
      "run": "node --test test/*.test.js"
    },
    {
      "id": "no-dependencies",
      "outcome": "no packages were installed",
      "run": "test ! -e node_modules"
    },
    {
      "id": "spec-cases",
      "outcome": "the program follows the written specification on the validator's own inputs",
      "run": "node src/cli.js",
      "cases": "reference/cases.json"
    }
  ]
}

