const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line = null) {
    super(message)
    this.line = line
  }
}

/**
 * Parses the raw standard input text into `{ candidates, ballots }`, where
 * `candidates` is the array of declared names in declaration order and
 * `ballots` is an array of `{ count, names }`. Throws `ParseError` on any
 * violation of the input format.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ParseError('expected candidates <name>...', lineNumber)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT_RE.test(countText)) {
        throw new ParseError('count must be a positive integer', lineNumber)
      }
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count: Number(countText), names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNumber)
    }
  }

  if (candidates === null) {
    throw new ParseError('no candidates', null)
  }

  return { candidates, ballots }
}
