 * The instant-runoff count itself, independent of input parsing and output
 * formatting.
 */

/**
 * Runs the count and returns `{ rounds, winner }`, where `rounds` is an
 * array of `{ counts, exhausted, eliminated }` in round order (`counts` is
 * an array of `{ name, votes }` sorted by descending votes then ascending
 * name; `eliminated` is the name eliminated after that round, or `null` for
 * the final round) and `winner` is the winning name or `null`.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) {
      votes.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }
    history.push(votes)

    const activeTotal = ballots.reduce((sum, b) => sum + b.count, 0) - exhausted

    const counts = [...continuing]
      .map((name) => ({ name, votes: votes.get(name) }))
      .sort((a, b) => b.votes - a.votes || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    if (activeTotal === 0) {
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const majority = counts.find((c) => c.votes * 2 > activeTotal)
    if (majority !== undefined) {
      winner = majority.name
      rounds.push({ counts, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(continuing, votes, history)
    rounds.push({ counts, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}

/**
 * Chooses the candidate to eliminate: the one with fewest votes this round,
 * breaking ties by comparing per-round vote history from the first round,
 * and breaking any remaining tie by picking the name that sorts last.
 */
function pickElimination(continuing, votes, history) {
  const minVotes = Math.min(...[...continuing].map((name) => votes.get(name)))
  let tied = [...continuing].filter((name) => votes.get(name) === minVotes)

  if (tied.length > 1) {
    for (const roundVotes of history) {
      if (tied.length === 1) break
      const roundMin = Math.min(...tied.map((name) => roundVotes.get(name)))
      tied = tied.filter((name) => roundVotes.get(name) === roundMin)
    }
  }

  if (tied.length === 1) {
    return tied[0]
  }
  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

